// vite hmr data
declare module 'virtual:valaxy-cover-components' {
  import type { Component } from 'vue'

  const components: ReadonlyMap<string, Component>
  export default components
}

// Generated by `node/plugins/layouts.ts`, runtime in `client/utils/layouts.ts`
declare module 'virtual:generated-layouts' {
  import type { Component, ComputedRef } from 'vue'
  import type { Router, RouteRecordNormalized, RouteRecordRaw } from 'vue-router'

  type LayoutName = string | false
  type LayoutProps = Record<string, unknown>

  /** Layout components by normalized name; lazy entries are loader functions. */
  export const layouts: Record<string, Component | (() => Promise<{ default: Component } | Component>)>
  export function createGetRoutes(router: Router, withLayout: true): RouteRecordNormalized[]
  export function createGetRoutes(router: Router, withLayout?: false): () => RouteRecordNormalized[]
  /** Wrap routes in the layout resolved from `meta.layout` (or the default layout). */
  export function setupLayouts(routes: readonly RouteRecordRaw[]): RouteRecordRaw[]
  /** Change the current page's layout until the router navigates to another path. */
  export function setPageLayout(name: LayoutName | null | undefined, props?: LayoutProps): void
  /** Reactive name of the current route's layout, `false` when it renders without one. */
  export function useLayout(): ComputedRef<LayoutName>
}

declare module '/@valaxyjs/config' {
  const config: string
  export default config
}

declare module '/@valaxyjs/context' {
  const ctx: string
  export default ctx
}
declare module '/@valaxyjs/addons' {
  import type { DefineComponent } from 'vue'

  const components: { props: any, component: DefineComponent<object, object, any> }[]
  export default components
}

declare module '/@valaxyjs/locales' {
  const messages: object
  export default messages
}

// Types for virtual modules
// `#valaxy/*` is an alias for `/@valaxyjs/*`, because TS will consider `/@valaxyjs/*` as an absolute path that we can't override

declare module '/@valaxyjs/redirects' {
  import type { RouteRecordRaw } from 'vue-router'

  export const redirectRoutes: RouteRecordRaw[]

  export const useVueRouter: boolean
}

declare module '#valaxy/styles' {
  // side-effects only
  const styles: string
  export default styles
}

declare module '@localSearchIndex' {
  const index: Record<string, () => Promise<{ default: string }>>
  export default index
}

// valaxy features
declare module '#valaxy/blog/collections' {
  import type { CollectionConfig } from './types'

  const collections: CollectionConfig[]
  export default collections
}

declare module '@intlify/unplugin-vue-i18n/messages' {
  import type { I18nOptions } from 'vue-i18n'

  const messages: I18nOptions['messages']
  export default messages
}
